?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Live Display</title><style>html,body{margin:0;width:100%;height:100%;background:#000;overflow:hidden}iframe{display:block;width:100vw;height:100vh;border:0;background:#000}.fx{pointer-events:none;position:fixed;inset:0;z-index:10;display:none;overflow:hidden}.fx.on{display:block}.fx canvas{position:absolute;inset:0;width:100%;height:100%}.cinema-vignette{position:absolute;inset:0;background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.72) 100%);opacity:0;transition:opacity .45s}.drumroll .cinema-vignette{opacity:1}.stage-light{position:absolute;top:-35%;width:42%;height:145%;filter:blur(18px);mix-blend-mode:screen;opacity:0;transform-origin:50% 0;background:linear-gradient(180deg,rgba(255,239,181,.8),rgba(255,190,74,.16) 58%,transparent 82%)}.drumroll .stage-light{opacity:.75;animation:sweep 1.35s cubic-bezier(.45,0,.55,1) infinite alternate}.stage-light.left{left:-4%;transform:rotate(18deg)}.stage-light.right{right:-4%;transform:rotate(-18deg);animation-delay:-.68s}.drum-core{position:absolute;left:50%;top:50%;width:min(29vw,430px);aspect-ratio:1;border-radius:50%;transform:translate(-50%,-50%) scale(.25);opacity:0;border:clamp(3px,.4vw,8px) solid rgba(255,223,132,.9);box-shadow:0 0 35px #ffcf66,0 0 120px rgba(220,25,65,.9),inset 0 0 70px rgba(255,215,110,.45)}.drumroll .drum-core{animation:drumBeat .42s ease-in-out infinite alternate}.drum-line{position:absolute;left:50%;top:50%;width:8px;height:62vh;border-radius:99px;background:linear-gradient(#fff,rgba(255,200,76,.05));filter:drop-shadow(0 0 14px #ffd66f);transform-origin:50% 0;opacity:0}.drumroll .drum-line{animation:radialHit .84s ease-out infinite}.drum-line:nth-of-type(2){transform:rotate(60deg);animation-delay:-.14s}.drum-line:nth-of-type(3){transform:rotate(120deg);animation-delay:-.28s}.drum-line:nth-of-type(4){transform:rotate(180deg);animation-delay:-.42s}.dr