function fireworks(){let last=0,launched=0;burst(innerWidth*.28,innerHeight*.3,64);burst(innerWidth*.72,innerHeight*.24,64);function frame(t){fxFrame=requestAnimationFrame(frame);if(document.hidden||t-lastFxPaint<42)return;lastFxPaint=t;ctx.clearRect(0,0,innerWidth,innerHeight);if(t-last>650&&launched<7){last=t;launched++;if(rockets.length<2)rockets.push({x:innerWidth*(.08+Math.random()*.84),y:innerHeight+20,vx:(Math.random()-.5)*1.1,vy:-(9+Math.random()*5),target:innerHeight*(.1+Math.random()*.5),color:palette[Math.floor(Math.random()*palette.length)]})}for(let i=rockets.length-1;i>=0;i--){const r=rockets[i];r.x+=r.vx*2;r.y+=r.vy*2;r.vy+=.07;ctx.beginPath();ctx.moveTo(r.x,r.y+24);ctx.lineTo(r.x,r.y);ctx.strokeStyle=r.color;ctx.lineWidth=2.5;ctx.stroke();if(r.y<=r.target||r.vy>0){burst(r.x,r.y,48+Math.floor(Math.random()*24));rockets.splice(i,1)}}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.trail.unshift([p.x,p.y]);if(p.trail.length>2)p.trail.pop();p.x+=p.vx*2;p.y+=p.vy*2;p.vx*=.97;p.vy=p.vy*.97+.12;p.life-=p.decay*2;ctx.beginPath();p.trail.forEach((q,n)=>n?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.strokeStyle=p.color;ctx.globalAlpha=Math.max(0,p.life);ctx.lineWidth=p.size;ctx.stroke();if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1}fxFrame=requestAnimationFrame(frame);fxTimer=setTimeout(stopEffect,7600)}
function confetti(){const colors=['#f5c451','#ef233c','#ffffff','#2563eb','#14b8a6','#9333ea'];for(let i=0;i<320;i++)particles.push({x:Math.random()*innerWidth,y:-Math.random()*innerHeight*1.2,w:5+Math.random()*12,h:3+Math.random()*7,vx:(Math.random()-.5)*3,vy:2.2+Math.random()*5,rot:Math.random()*6.28,vr:(Math.random()-.5)*.24,color:colors[i%colors.length],wave:Math.random()*6.28});function frame(){ctx.clearRect(0,0,innerWidth,innerHeight);particles.forEach(p=>{p.wave+=.035;p.x+=p.vx+Math.sin(p.wave)*1.2;p.y+=p.vy;p.rot+=p.vr;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillStyle=p.color;ctx.shadowBlur=7;ctx.shadowColor='rgba(255,255,255,.32)';ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);ctx.restore()});particles=particles.filter(p=>p.y<innerHeight+35);if(particles.length)fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame);fxTimer=setTimeout(stopEffect,8000)}
