function countdown(){const start=performance.now();function frame(t){const age=t-start,number=Math.max(1,5-Math.floor(age/1000)),pulse=(age%1000)/1000;ctx.clearRect(0,0,innerWidth,innerHeight);ctx.fillStyle='rgba(3,5,9,.88)';ctx.fillRect(0,0,innerWidth,innerHeight);ctx.save();ctx.translate(innerWidth/2,innerHeight/2);ctx.scale(.72+pulse*.42,.72+pulse*.42);ctx.globalAlpha=1-pulse*.38;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`900 ${Math.min(innerWidth,innerHeight)*.46}px Arial`;ctx.shadowBlur=70;ctx.shadowColor='#ffcf45';ctx.fillStyle='#fff';ctx.fillText(String(number),0,0);ctx.restore();if(age<5000)fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame)}
function goldRain(){for(let i=0;i<420;i++)particles.push({x:Math.random()*innerWidth,y:-Math.random()*innerHeight*1.4,w:2+Math.random()*6,h:8+Math.random()*22,vx:(Math.random()-.5)*1.4,vy:2.5+Math.random()*6,rot:Math.random()*6.28,vr:(Math.random()-.5)*.18,color:i%5?'#f4c95d':'#fff2b2',wave:Math.random()*6.28});function frame(){ctx.clearRect(0,0,innerWidth,innerHeight);particles.forEach(p=>{p.wave+=.025;p.x+=p.vx+Math.sin(p.wave)*.8;p.y+=p.vy;p.rot+=p.vr;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);const g=ctx.createLinearGradient(-p.w,0,p.w,0);g.addColorStop(0,'#7a4b00');g.addColorStop(.5,p.color);g.addColorStop(1,'#fff8cf');ctx.fillStyle=g;ctx.shadowBlur=12;ctx.shadowColor='#ffd66b';ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);ctx.restore()});particles=particles.filter(p=>p.y<innerHeight+40);if(particles.length)fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame);fxTimer=setTimeout(stopEffect,8500)}
function laserSweep(){const start=performance.now();function frame(t){ctx.clearRect(0,0,innerWidth,innerHeight);const age=t-start;ctx.globalCompositeOperation='lighter';for(let i=0;i<14;i++){const phase=age*.0017+i*.58,x=innerWidth/2+Math.sin(phase)*innerWidth*.12,y=innerHeight*.08;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(innerWidth/2+Math.sin(phase*1.37+i)*innerWidth*.75,innerHeight*1.08);ctx.strokeStyle=i%3===0?'rgba(255,55,110,.58)':i%3===1?'rgba(40,210,255,.5)':'rgba(255,214,90,.48)';ctx.lineWidth=1.5+(i%4);ctx.shadowBlur=22;ctx.shadowColor=ctx.strokeStyle;ctx.stroke()}ctx.globalCompositeOperation='source-over';ctx.shadowBlur=0;fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame);fxTimer=setTimeout(stopEffect,6200)}
function championImpact(){const start=performance.now(),cx=innerWidth/2,cy=innerHeight/2;burst(cx,cy,220);function frame(t){ctx.clearRect(0,0,innerWidth,innerHeight);const age=t-start,p=Math.min(1,age/1500),r=p*Math.max(innerWidth,innerHeight)*.78;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.strokeStyle=`rgba(255,220,125,${1-p})`;ctx.lineWidth=Math.max(2,26*(1-p));ctx.shadowBlur=55;ctx.shadowColor='#ffd36b';ctx.stroke();particles.forEach((q,i)=>{q.x+=q.vx;q.y+=q.vy;q.vx*=.975;q.vy*=.975;q.life-=.008;ctx.beginPath();ctx.arc(q.x,q.y,q.size*1.6,0,Math.PI*2);ctx.fillStyle=q.color;ctx.globalAlpha=Math.max(0,q.life);ctx.shadowBlur=24;ctx.shadowColor=q.color;ctx.fill();if(q.life<=0)particles.splice(i,1)});ctx.globalAlpha=1;if(age<4300)fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame);fxTimer=setTimeout(stopEffect,4500)}
