function sustainedRain(gold=false){const colors=gold?['#9b6500','#f4c95d','#fff2b2','#d99b20']:['#f5c451','#ef233c','#ffffff','#2563eb','#14b8a6','#9333ea'];for(let i=0;i<360;i++)particles.push({x:Math.random()*innerWidth,y:Math.random()*innerHeight,w:gold?2+Math.random()*6:5+Math.random()*12,h:gold?8+Math.random()*22:3+Math.random()*7,vx:(Math.random()-.5)*(gold?1.4:3),vy:2.2+Math.random()*5,rot:Math.random()*6.28,vr:(Math.random()-.5)*.22,color:colors[i%colors.length],wave:Math.random()*6.28});function frame(){ctx.clearRect(0,0,innerWidth,innerHeight);particles.forEach(p=>{p.wave+=.03;p.x+=p.vx+Math.sin(p.wave)*(gold?.8:1.2);p.y+=p.vy;p.rot+=p.vr;if(p.y>innerHeight+35){p.y=-35;p.x=Math.random()*innerWidth}ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);ctx.fillStyle=p.color;ctx.shadowBlur=gold?13:7;ctx.shadowColor=gold?'#ffd66b':'rgba(255,255,255,.32)';ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);ctx.restore()});fxFrame=requestAnimationFrame(frame)}fxFrame=requestAnimationFrame(frame)}
