function rankedDrum(place){drumroll();clearTimeout(fxTimer);const strength={5:.38,4:.52,3:.68,2:.84,1:1}[place]||.72;fx.style.opacity=String(.45+strength*.55);fx.style.filter=`saturate(${.8+strength*.7}) brightness(${.8+strength*.35})`;document.querySelector('.drum-core').style.width=`min(${16+strength*16}vw,${240+strength*230}px)`}
function effect(s){const key=[s.effect_type,s.effect_version].join('|');if(key===effectFingerprint)return;effectFingerprint=key;stopEffect();if(!s.effect_type)return;sizeCanvas();Object.assign(fx.style,{zIndex:'2147483647',background:'transparent',display:'block',position:'fixed',inset:'0',pointerEvents:'none',opacity:'1',filter:'none'});const drumMatch=String(s.effect_type).match(/^drumroll(?:_([1-5]))?$/);fx.className='fx on '+(drumMatch?'drumroll':s.effect_type);if(s.effect_type==='countdown')countdown();else if(s.effect_type==='fireworks')sustainedFireworks();else if(s.effect_type==='confetti')sustainedRain(false);else if(drumMatch)rankedDrum(Number(drumMatch[1]||0));else if(s.effect_type==='gold_rain')sustainedRain(true);else if(s.effect_type==='laser_sweep'){laserSweep();clearTimeout(fxTimer)}else if(s.effect_type==='champion_impact')sustainedChampion()}
