function load(s){effect(s);const fp=[s.state_version,s.data_version||0,s.screen_type,s.round_id,s.page_number,s.reveal_place].join('|');if(fp!==fingerprint){fingerprint=fp;const endpoint=s.screen_type==='winners'&&!s.reveal_place?'podium-ready.php':s.screen_type==='final_results'?'final-relative-placement.php':'feed.php';feed.src=endpoint+'?token='+encodeURIComponent(token)+'&v='+encodeURIComponent(fp)+'&_='+Date.now()}const tf=[s.auto_page,s.page_delay_seconds,s.total_pages,s.screen_type].join('|');if(tf===timerFingerprint)return;timerFingerprint=tf;clearInterval(pageTimer);if(!s.loop_enabled&&s.auto_page&&s.total_pages>1&&['competitors','callbacks','finalists'].includes(s.screen_type))pageTimer=setInterval(async()=>{try{await fetch('advance.php?token='+encodeURIComponent(token),{method:'POST',cache:'no-store'});await tick()}catch(e){}},Number(s.page_delay_seconds)*1000)}
async function tick(){if(document.hidden||busy||Date.now()<blockedUntil)return;busy=true;try{const r=await fetch('state.php?token='+encodeURIComponent(token)+'&_='+Date.now(),{cache:'no-store'});if(r.status===429){blockedUntil=Date.now()+60000;return}const s=await r.json();if(s&&s.ok)load(s)}catch(e){}finally{busy=false}}tick();setInterval(tick,2500);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});
